# GC content and melting temp estimate (Wallace rule, short oligos)
def gc_content(seq):
    seq = seq.upper()
    gc = seq.count("G") + seq.count("C")
    return 100.0*gc/len(seq)
def wallace_tm(seq):
    seq = seq.upper()
    return 2*(seq.count("A")+seq.count("T")) + 4*(seq.count("G")+seq.count("C"))
s = "ATGCGTACGTTAGC"
print(f"GC: {gc_content(s):.1f}%  Tm~{wallace_tm(s)}C")
